package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.widget.TextView;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.google.android.material.button.MaterialButtonToggleGroup;
public class ReadingFragment extends Fragment{
    private ReadingRepository repo;private ReadingAdapter adapter;private ProgressStore progress;private TextView stats;private String level="A1";
    @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_reading,c,false);repo=ReadingRepository.get(requireContext());progress=new ProgressStore(requireContext());stats=v.findViewById(R.id.text_reading_stats);RecyclerView rv=v.findViewById(R.id.recycler_readings);rv.setLayoutManager(new LinearLayoutManager(requireContext()));adapter=new ReadingAdapter(progress,p->((MainActivity)requireActivity()).openReading(p.id));rv.setAdapter(adapter);MaterialButtonToggleGroup g=v.findViewById(R.id.group_read_level);g.addOnButtonCheckedListener((group,id,checked)->{if(!checked)return;level=id==R.id.button_read_a2?"A2":(id==R.id.button_read_b1?"B1":"A1");refresh();});g.check(R.id.button_read_a1);refresh();return v;}
    private void refresh(){adapter.submit(repo.byLevel(level));int att=progress.auxiliaryAttempts("reading"),acc=progress.auxiliaryAccuracy("reading");stats.setText("18篇生活化短文 · 当前 "+level+" 共 "+repo.byLevel(level).size()+"篇 · 阅读理解 "+(att==0?"尚未测试":(acc+"%")));}
}
